/**
 * Procedural sound effects.
 *
 * The arcade machine's audio is generated by a handful of oscillators inside
 * the cabinet; this reproduces that idea with the Web Audio API so there are no
 * sample files to ship.
 */

import type { GameEvent } from '../engine/types.js';

type Ctor = typeof AudioContext;

export class GameAudio {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private noiseBuffer: AudioBuffer | null = null;
  private lastPlayed = new Map<string, number>();
  muted = false;

  /** Browsers require a gesture before audio starts. */
  unlock(): void {
    if (!this.ctx) this.init();
    if (this.ctx?.state === 'suspended') void this.ctx.resume();
  }

  private init(): void {
    const CtorImpl: Ctor | undefined =
      window.AudioContext ?? (window as unknown as { webkitAudioContext?: Ctor }).webkitAudioContext;
    if (!CtorImpl) return;
    const ctx = new CtorImpl();
    const master = ctx.createGain();
    master.gain.value = 0.2;
    master.connect(ctx.destination);
    this.ctx = ctx;
    this.master = master;

    const length = Math.floor(ctx.sampleRate * 0.8);
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = buffer;
  }

  setMuted(muted: boolean): void {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.2, this.ctx.currentTime, 0.02);
    }
  }

  /** Rate-limit a cue so overlapping kills do not turn into a wall of noise. */
  private throttled(key: string, minimumGap: number): boolean {
    if (!this.ctx) return false;
    const now = this.ctx.currentTime;
    const last = this.lastPlayed.get(key) ?? -1;
    if (now - last < minimumGap) return false;
    this.lastPlayed.set(key, now);
    return true;
  }

  private tone(
    frequency: number,
    duration: number,
    options: {
      type?: OscillatorType;
      gain?: number;
      sweepTo?: number;
      delay?: number;
      attack?: number;
    } = {},
  ): void {
    const ctx = this.ctx;
    const master = this.master;
    if (!ctx || !master) return;
    const { type = 'square', gain = 0.18, sweepTo, delay = 0, attack = 0.005 } = options;
    const start = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(frequency, start);
    if (sweepTo !== undefined) osc.frequency.exponentialRampToValueAtTime(Math.max(20, sweepTo), start + duration);

    const env = ctx.createGain();
    env.gain.setValueAtTime(0.0001, start);
    env.gain.exponentialRampToValueAtTime(gain, start + attack);
    env.gain.exponentialRampToValueAtTime(0.0001, start + duration);

    osc.connect(env);
    env.connect(master);
    osc.start(start);
    osc.stop(start + duration + 0.02);
  }

  private noise(
    duration: number,
    options: { gain?: number; from?: number; to?: number; delay?: number; type?: BiquadFilterType } = {},
  ): void {
    const ctx = this.ctx;
    const master = this.master;
    const buffer = this.noiseBuffer;
    if (!ctx || !master || !buffer) return;
    const { gain = 0.22, from = 1600, to = 220, delay = 0, type = 'lowpass' } = options;
    const start = ctx.currentTime + delay;

    const source = ctx.createBufferSource();
    source.buffer = buffer;

    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(from, start);
    filter.frequency.exponentialRampToValueAtTime(Math.max(40, to), start + duration);

    const env = ctx.createGain();
    env.gain.setValueAtTime(gain, start);
    env.gain.exponentialRampToValueAtTime(0.0001, start + duration);

    source.connect(filter);
    filter.connect(env);
    env.connect(master);
    source.start(start);
    source.stop(start + duration + 0.02);
  }

  playEvents(events: GameEvent[]): void {
    if (!this.ctx || this.muted) return;
    for (const event of events) this.play(event);
  }

  play(event: GameEvent): void {
    if (!this.ctx || this.muted) return;
    switch (event.type) {
      case 'shoot':
        if (this.throttled('shoot', 0.05)) this.tone(920, 0.09, { type: 'square', gain: 0.12, sweepTo: 380 });
        break;
      case 'enemyShoot':
        if (this.throttled('enemyShoot', 0.08)) this.tone(300, 0.11, { type: 'sawtooth', gain: 0.08, sweepTo: 150 });
        break;
      case 'enemyExplode':
        if (this.throttled('enemyExplode', 0.045)) {
          this.noise(0.22, { gain: 0.2, from: 1800, to: 200 });
          this.tone(event.kind === 'boss' ? 180 : 300, 0.12, { type: 'triangle', gain: 0.1, sweepTo: 90 });
        }
        break;
      case 'playerExplode':
        this.noise(0.7, { gain: 0.3, from: 1200, to: 60 });
        this.tone(220, 0.75, { type: 'sine', gain: 0.22, sweepTo: 40 });
        break;
      case 'capture':
        this.tone(260, 0.55, { type: 'sine', gain: 0.18, sweepTo: 900 });
        this.tone(900, 0.6, { type: 'sine', gain: 0.12, sweepTo: 180, delay: 0.5 });
        break;
      case 'rescue':
        [523, 659, 784, 1046].forEach((f, i) =>
          this.tone(f, 0.16, { type: 'square', gain: 0.12, delay: i * 0.09 }),
        );
        break;
      case 'stageStart':
        [392, 523, 659, 784].forEach((f, i) =>
          this.tone(f, 0.18, { type: 'triangle', gain: 0.14, delay: i * 0.11 }),
        );
        break;
      case 'stageClear':
        [523, 659, 784, 1046, 1318].forEach((f, i) =>
          this.tone(f, 0.2, { type: 'square', gain: 0.11, delay: i * 0.1 }),
        );
        break;
      case 'extraLife':
        this.tone(1046, 0.12, { type: 'square', gain: 0.14 });
        this.tone(1568, 0.2, { type: 'square', gain: 0.14, delay: 0.12 });
        break;
      case 'groupBonus':
      case 'perfect':
        [784, 988, 1175, 1568].forEach((f, i) =>
          this.tone(f, 0.14, { type: 'triangle', gain: 0.12, delay: i * 0.07 }),
        );
        break;
      case 'gameOver':
        [392, 330, 262, 196].forEach((f, i) =>
          this.tone(f, 0.42, { type: 'sawtooth', gain: 0.12, delay: i * 0.22 }),
        );
        break;
      case 'victory':
        [523, 659, 784, 1046, 1318, 1568].forEach((f, i) =>
          this.tone(f, 0.28, { type: 'triangle', gain: 0.14, delay: i * 0.13 }),
        );
        [1046, 1318, 1568, 2093].forEach((f, i) =>
          this.tone(f, 0.5, { type: 'square', gain: 0.07, delay: 0.9 + i * 0.16 }),
        );
        break;
      case 'dive':
        if (this.throttled('dive', 0.3)) this.tone(660, 0.16, { type: 'sine', gain: 0.05, sweepTo: 220 });
        break;
      case 'shotJam':
        // A dull click as a shot drops into a slot that will never release it.
        if (this.throttled('shotJam', 0.12)) {
          this.noise(0.08, { gain: 0.12, from: 900, to: 120 });
          this.tone(120, 0.09, { type: 'square', gain: 0.05, sweepTo: 60 });
        }
        break;
      case 'noFire':
        // The famous failure: the fleet goes quiet.
        this.tone(440, 0.18, { type: 'sine', gain: 0.1, sweepTo: 330 });
        this.tone(330, 0.24, { type: 'sine', gain: 0.1, sweepTo: 220, delay: 0.16 });
        break;
      default:
        break;
    }
  }
}
